1	// Package batchreg registers supply-chain batches in a local JSON file.
2	//
3	// The registry file format is public and stable:
4	//
5	//	{
6	//	  "version": 1,
7	//	  "batches": [
8	//	    {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
9	//	  ]
10	//	}
11	//
12	// Batch ids are unique per file (compared byte for byte, so casing and
13	// interior characters matter). Re-registering an existing id with the same
14	// product, quantity and unit is an idempotent duplicate confirmation; any
15	// differing field is rejected without touching stored records.
16	package batchreg
17	
18	import (
19		"bytes"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"io"
24		"io/fs"
25		"os"
26		"path/filepath"
27		"regexp"
28		"strconv"
29		"strings"
30	)
31	
32	// FormatVersion is the only registry file format understood by this build.
33	const FormatVersion = 1
34	
35	// MaxQuantity is the inclusive upper bound for a batch quantity.
36	const MaxQuantity = int64(1<<63 - 1)
37	
38	var quantityPattern = regexp.MustCompile(`^[0-9]+$`)
39	
40	// Batch is the four-piece record of one supply-chain batch.
41	type Batch struct {
42		Batch    string `json:"batch"`
43		Product  string `json:"product"`
44		Quantity int64  `json:"quantity"`
45		Unit     string `json:"unit"`
46	}
47	
48	// Registry is the on-disk registry file.
49	type Registry struct {
50		Version int     `json:"version"`
51		Batches []Batch `json:"batches"`
52	}
53	
54	// Input is a normalized registration request.
55	type Input struct {
56		Batch    string
57		Product  string
58		Quantity int64
59		Unit     string
60	}
61	
62	// Outcome reports what Register did.
63	type Outcome struct {
64		Batch   Batch
65		Created bool // true when a record was added, false for an identical repeat
66	}
67	
68	// ConflictError reports that a batch id is already held by a different record.
69	// Fields lists every differing member among "product", "quantity" and "unit".
70	type ConflictError struct {
71		Batch  string
72		Fields []string
73	}
74	
75	func (e *ConflictError) Error() string {
76		return fmt.Sprintf("batch %q is already registered with conflicting field(s): %s; the existing record cannot be overwritten",
77			e.Batch, strings.Join(e.Fields, ", "))
78	}
79	
80	// DuplicateIDError reports two stored records sharing one batch id.
81	type DuplicateIDError struct {
82		Batch string
83	}
84	
85	func (e *DuplicateIDError) Error() string {
86		return fmt.Sprintf("registry contains multiple records for batch %q", e.Batch)
87	}
88	
89	// NormalizeField trims leading and trailing whitespace; the result must stay
90	// non-empty. Interior characters, including interior whitespace, are kept,
91	// and casing is preserved so "B1" and "b1" are different values.
92	func NormalizeField(value string) (string, error) {
93		trimmed := strings.TrimSpace(value)
94		if trimmed == "" {
95			return "", errors.New("value must not be empty after trimming whitespace")
96		}
97		return trimmed, nil
98	}
99	
100	// ParseQuantity accepts a decimal positive integer made only of ASCII digits
101	// 0-9. Leading zeros are allowed; the numeric value is what gets stored and
102	// compared. Zero, signs, fractions, non-ASCII digits and values above the
103	// signed 64-bit maximum are rejected.
104	func ParseQuantity(text string) (int64, error) {
105		if !quantityPattern.MatchString(text) {
106			return 0, fmt.Errorf("quantity %q must be a positive decimal integer made only of digits 0-9", text)
107		}
108		value, err := strconv.ParseInt(text, 10, 64)
109		if err != nil {
110			return 0, fmt.Errorf("quantity %q must be a positive integer no greater than %d", text, MaxQuantity)
111		}
112		if value == 0 {
113			return 0, fmt.Errorf("quantity %q must be greater than zero", text)
114		}
115		return value, nil
116	}
117	
118	// Load reads the registry at path. A missing file yields an empty registry
119	// with existed == false. An existing file that is empty, not parseable as
120	// the public format, of an unsupported version, or holding duplicate batch
121	// ids is an error: callers must never overwrite such a file as if it were a
122	// fresh registry.
123	func Load(path string) (reg *Registry, existed bool, err error) {
124		data, err := os.ReadFile(path)
125		if err != nil {
126			if errors.Is(err, fs.ErrNotExist) {
127				return &Registry{Version: FormatVersion}, false, nil
128			}
129			return nil, false, fmt.Errorf("cannot read registry %q: %w", path, err)
130		}
131		if len(bytes.TrimSpace(data)) == 0 {
132			return nil, true, fmt.Errorf("registry file %q is empty; refusing to replace it with a new registry", path)
133		}
134		reg, err = decode(data)
135		if err != nil {
136			return nil, true, fmt.Errorf("cannot parse registry %q as version %d JSON: %w", path, FormatVersion, err)
137		}
138		if err := validate(reg); err != nil {
139			return nil, true, fmt.Errorf("registry %q is not usable: %w", path, err)
140		}
141		return reg, true, nil
142	}
143	
144	func decode(data []byte) (*Registry, error) {
145		dec := json.NewDecoder(bytes.NewReader(data))
146		dec.DisallowUnknownFields()
147		reg := &Registry{}
148		if err := dec.Decode(reg); err != nil {
149			return nil, err
150		}
151		var extra json.RawMessage
152		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
153			if err == nil {
154				return nil, errors.New("unexpected data after registry object")
155			}
156			return nil, err
157		}
158		if reg.Version != FormatVersion {
159			return nil, fmt.Errorf("unsupported registry version: got %d, want %d", reg.Version, FormatVersion)
160		}
161		return reg, nil
162	}
163	
164	func validate(reg *Registry) error {
165		seen := make(map[string]struct{}, len(reg.Batches))
166		for i, b := range reg.Batches {
167			if b.Batch == "" || b.Product == "" || b.Unit == "" {
168				return fmt.Errorf("batches[%d] (batch %q): batch, product and unit must all be non-empty", i, b.Batch)
169			}
170			if b.Quantity <= 0 {
171				return fmt.Errorf("batches[%d] (batch %q): quantity must be a positive integer", i, b.Batch)
172			}
173			if _, dup := seen[b.Batch]; dup {
174				return &DuplicateIDError{Batch: b.Batch}
175			}
176			seen[b.Batch] = struct{}{}
177		}
178		return nil
179	}
180	
181	// Register adds in to reg, or confirms the identical record already stored
182	// under the same batch id. A batch id held by a record differing in product,
183	// quantity or unit produces a *ConflictError and leaves reg untouched. The
184	// zero Outcome is returned together with the error.
185	func Register(reg *Registry, in Input) (Outcome, error) {
186		if reg.Version != FormatVersion {
187			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
188		}
189		if in.Batch == "" || in.Product == "" || in.Unit == "" {
190			return Outcome{}, errors.New("batch, product and unit must be non-empty")
191		}
192		if in.Quantity <= 0 || in.Quantity > MaxQuantity {
193			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
194		}
195		for _, b := range reg.Batches {
196			if b.Batch != in.Batch {
197				continue
198			}
199			var diffs []string
200			if b.Product != in.Product {
201				diffs = append(diffs, "product")
202			}
203			if b.Quantity != in.Quantity {
204				diffs = append(diffs, "quantity")
205			}
206			if b.Unit != in.Unit {
207				diffs = append(diffs, "unit")
208			}
209			if len(diffs) > 0 {
210				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
211			}
212			return Outcome{Batch: b, Created: false}, nil
213		}
214		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
215		reg.Batches = append(reg.Batches, b)
216		return Outcome{Batch: b, Created: true}, nil
217	}
218	
219	// Save atomically writes reg to path, replacing the file only after the new
220	// content is fully on disk so an existing registry stays usable on failure.
221	// Records are serialized in their current order; the file is created with
222	// 0644 permissions or, when replacing an existing file, with its permissions.
223	func Save(path string, reg *Registry) error {
224		if reg.Version != FormatVersion {
225			return fmt.Errorf("cannot write registry format version %d", reg.Version)
226		}
227		mode := os.FileMode(0o644)
228		if info, err := os.Stat(path); err == nil {
229			mode = info.Mode().Perm()
230		} else if !errors.Is(err, fs.ErrNotExist) {
231			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
232		}
233	
234		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
235			return fmt.Errorf("cannot save registry %q: %w", path, err)
236		}
237	
238		var buf bytes.Buffer
239		enc := json.NewEncoder(&buf)
240		enc.SetEscapeHTML(false)
241		enc.SetIndent("", "  ")
242		if err := enc.Encode(reg); err != nil {
243			return fmt.Errorf("cannot encode registry %q: %w", path, err)
244		}
245	
246		tmp, err := os.CreateTemp(filepath.Dir(path), ".govflow-registry-*.tmp")
247		if err != nil {
248			return fmt.Errorf("cannot save registry %q: %w", path, err)
249		}
250		tmpName := tmp.Name()
251		abort := func(cause error) error {
252			tmp.Close()
253			os.Remove(tmpName)
254			return fmt.Errorf("cannot save registry %q: %w", path, cause)
255		}
256		if _, err := tmp.Write(buf.Bytes()); err != nil {
257			return abort(err)
258		}
259		if err := tmp.Chmod(mode); err != nil {
260			return abort(err)
261		}
262		if err := tmp.Sync(); err != nil {
263			return abort(err)
264		}
265		if err := tmp.Close(); err != nil {
266			os.Remove(tmpName)
267			return fmt.Errorf("cannot save registry %q: %w", path, err)
268		}
269		if err := os.Rename(tmpName, path); err != nil {
270			os.Remove(tmpName)
271			return fmt.Errorf("cannot save registry %q: %w", path, err)
272		}
273		return nil
274	}
