// ManifestRecordError reports a manifest record that is structurally invalid
// or carries a quantity outside the accepted range. Position is the record's
// 1-based position in the manifest.
type ManifestRecordError struct {
	Position int
	Batch    string // normalized batch id when available, otherwise ""
	Reason   string
}

func (e *ManifestRecordError) Error() string {
	if e.Batch != "" {
		return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
	}
	return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
}

// ManifestConflictError reports that a manifest record disagrees with the
// record already registered, or introduced earlier in the same manifest,
// under the same batch id. Position is the record's 1-based position in the
// manifest and Fields lists every differing member among "product",
// "quantity" and "unit" in that order.
type ManifestConflictError struct {
	Position int
	Batch    string
	Fields  []string
	Source   string // "registry" or "manifest"
	PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
}

func (e *ManifestConflictError) Error() string {
	if e.Source == "manifest" {
		return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
			e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
	}
	return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
		e.Position, e.Batch, strings.Join(e.Fields, ", "))
}

// ParseManifest decodes data as a non-empty JSON array holding exactly the
// four required fields batch, product, quantity and unit per element. The
// three text fields must be JSON strings that are not blank after trimming;
// quantity must be a JSON integer (no strings, fractions or exponents) in
// the range 1..MaxQuantity. An empty file, empty array, non-array document
// or any malformed record is rejected. The manifest bytes are never written.
func ParseManifest(data []byte) ([]Input, error) {
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, errors.New("manifest file is empty")
	}
	type rawRecord struct {
		Batch    string           `json:"batch"`
		Product  string           `json:"product"`
		Quantity *json.Number     `json:"quantity"`
		Unit     string           `json:"unit"`
	}
	var records []rawRecord
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	if err := dec.Decode(&records); err != nil {
		return nil, fmt.Errorf("manifest must be a non-empty JSON array of records: %w", err)
	}
	var extra json.RawMessage
	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return nil, errors.New("manifest has unexpected data after the array")
		}
		return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
	}
	if records == nil {
		return nil, errors.New("manifest must be a JSON array of records")
	}
	if len(records) == 0 {
		return nil, errors.New("manifest must contain at least one record")
	}

	inputs := make([]Input, 0, len(records))
	for i, r := range records {
		pos := i + 1
		batch, err := NormalizeField(r.Batch)
		if err != nil {
			return nil, &ManifestRecordError{Position: pos, Reason: "batch must be a non-empty JSON string with non-blank content: " + err.Error()}
		}
		product, err := NormalizeField(r.Product)
		if err != nil {
			return nil, &ManifestRecordError{Position: pos, Batch: batch, Reason: "product must be a non-empty JSON string with non-blank content: " + err.Error()}
		}
		unit, err := NormalizeField(r.Unit)
		if err != nil {
			return nil, &ManifestRecordError{Position: pos, Batch: batch, Reason: "unit must be a non-empty JSON string with non-blank content: " + err.Error()}
		}
		if r.Quantity == nil {
			return nil, &ManifestRecordError{Position: pos, Batch: batch, Reason: "quantity is required and must be a JSON integer"}
		}
		quantity, err := parseManifestQuantity(*r.Quantity)
		if err != nil {
			return nil, &ManifestRecordError{Position: pos, Batch: batch, Reason: err.Error()}
		}
		inputs = append(inputs, Input{Batch: batch, Product: product, Quantity: quantity, Unit: unit})
	}
	return inputs, nil
}

// parseManifestQuantity accepts exactly a JSON integer token in the range
// 1..MaxQuantity. Strings, fractions, exponents and out-of-range values are
// rejected instead of silently rounded.
func parseManifestQuantity(token json.Number) (int64, error) {
	text := token.String()
	for i := 0; i < len(text); i++ {
		c := text[i]
		if c < '0' || c > '9' {
			return 0, fmt.Errorf("quantity %s must be a JSON integer without sign, fraction or exponent", text)
		}
	}
	value, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("quantity %s must be a positive integer no greater than %d", text, MaxQuantity)
	}
	if value == 0 {
		return 0, fmt.Errorf("quantity %s must be greater than zero", text)
	}
	// Reject leading zeros: a JSON integer token with a leading zero is
	// already invalid JSON (encoding/json errors on it), but guard anyway.
	if len(text) > 1 && text[0] == '0' {
		return 0, fmt.Errorf("quantity %s must be a JSON integer without leading zeros", text)
	}
	return value, nil
