		return &usageError{
			msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
			usage: batchImportUsage,
		}
	}
	if *registryPath == "" || *inputPath == "" {
		var missing []string
		if *registryPath == "" {
			missing = append(missing, "--registry")
		}
		if *inputPath == "" {
			missing = append(missing, "--input")
		}
